import{_ as t,o as e,c as a,a2 as i}from"./chunks/framework.DGu13UIe.js";const k=JSON.parse('{"title":"第 45 课 · 动态联网与用户追问","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/45-web-search/doc.md"},"headers":[],"relativePath":"chapters/45-web-search.md","filePath":"chapters/45-web-search.md"}'),o={name:"chapters/45-web-search.md"};function d(n,s,r,h,l,c){return e(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="第-45-课-·-动态联网与用户追问" tabindex="-1">第 45 课 · 动态联网与用户追问 <a class="header-anchor" href="#第-45-课-·-动态联网与用户追问" aria-label="Permalink to &quot;第 45 课 · 动态联网与用户追问&quot;">​</a></h1><p><strong>约 40 分钟</strong> · <a href="/bagent/chapters/44-read-dispatch.html">第 44 课</a> 之后 · <strong>独立插件</strong></p><p>本课在 <a href="/bagent/chapters/44-read-dispatch.html">第 44 课</a> 上增加三块能力：</p><ol><li><strong>动态 <code>web_search</code></strong>（Tavily，有 Key 才注册）</li><li><strong>只读工具自动放行</strong>（合规 <code>stat_file</code> / <code>read_file</code> 等）</li><li><strong><code>ask_user_question</code></strong>（向用户追问，专用事件 + 等待输入）</li></ol><hr><h2 id="_1-动态-web-search" tabindex="-1">1. 动态 web_search <a class="header-anchor" href="#_1-动态-web-search" aria-label="Permalink to &quot;1. 动态 web_search&quot;">​</a></h2><p><a href="/bagent/chapters/09-tavily.html">第 9 课</a> 起就有 <code>web_search</code>，但若写死在 <code>toolDefinitions</code> 里，没 Key 时模型仍会白调一轮。</p><table tabindex="0"><thead><tr><th>机制</th><th>作用</th></tr></thead><tbody><tr><td><code>hasWebSearch()</code></td><td>读 <code>TAVILY_API_KEY</code></td></tr><tr><td><code>getToolDefinitions()</code></td><td>有 Key 才追加 <code>web_search</code></td></tr><tr><td><code>getPluginSystem()</code></td><td>提示里说明是否可联网</td></tr></tbody></table><p>Tavily <strong>Search</strong>（本课 <code>web_search</code>）按关键词搜；<strong>Extract</strong>（按 URL 抓正文）尚未实现，以后可加 <code>fetch_url</code>。</p><p>配置 Key：<code>~/.bagent/tavily-api-key</code> 或 <code>export TAVILY_API_KEY=tvly-...</code>，设置项 <strong><code>bagent45.tavilyApiKeyPath</code></strong>。</p><hr><h2 id="_2-只读工具自动放行" tabindex="-1">2. 只读工具自动放行 <a class="header-anchor" href="#_2-只读工具自动放行" aria-label="Permalink to &quot;2. 只读工具自动放行&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>自动放行</th></tr></thead><tbody><tr><td><code>pwd</code></td><td>✅</td></tr><tr><td><code>ls</code> / <code>stat_file</code> / <code>read_file</code> / <code>grep</code></td><td>✅ cwd 下且非 <code>.git</code> / <code>node_modules</code> / <code>.env</code></td></tr><tr><td><code>write_file</code> / <code>web_search</code> / <code>ask_user_question</code></td><td>❌</td></tr></tbody></table><p><code>ask_user_question</code> 不走审批条，见下一节。自动放行在工具行尾显示绿色 <strong>· 自动放行</strong>，不单独占一行。</p><hr><h2 id="_3-ask-user-question-用户追问" tabindex="-1">3. ask_user_question（用户追问） <a class="header-anchor" href="#_3-ask-user-question-用户追问" aria-label="Permalink to &quot;3. ask_user_question（用户追问）&quot;">​</a></h2><p>当 Agent <strong>缺关键信息</strong>且项目里读不到时，可调用：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;question&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你要部署到哪个环境：staging 还是 production？&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h3 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型 tool_call ask_user_question</span></span>
<span class="line"><span>  → loop 发 ToolCallStart</span></span>
<span class="line"><span>  → loop 发 AskUserPending（UI 显示问题 + 输入框 +「跳过」）</span></span>
<span class="line"><span>  → worker 等待 stdin：ask_user_answer / ask_user_skip</span></span>
<span class="line"><span>  → 写入 tool 结果，继续 Agent 循环</span></span></code></pre></div><p>与 <a href="/bagent/chapters/35-tool-approval.html">第 35 课</a> <strong>审批</strong>不同：这是<strong>问答</strong>，不是允许/拒绝执行。</p><h3 id="工具返回" tabindex="-1">工具返回 <a class="header-anchor" href="#工具返回" aria-label="Permalink to &quot;工具返回&quot;">​</a></h3><p>用户<strong>提交</strong>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;answer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;staging&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>用户<strong>跳过</strong>（或终端直接回车）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;用户不想填写此次信息补充，请你自行决定&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Agent 应读 <code>hint</code> 后<strong>自己想办法</strong>，不要反复追问同一件事。</p><p>系统提示要求：<strong>需要用户指定文件名、二选一等时，必须调 <code>ask_user_question</code>，禁止在正文里用「你想看哪个文件」代替。</strong></p><h3 id="代码位置" tabindex="-1">代码位置 <a class="header-anchor" href="#代码位置" aria-label="Permalink to &quot;代码位置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>agent/askUser.ts</code></td><td>解析问题、格式化返回、<code>AskUserTool</code> 类型</td></tr><tr><td><code>agent/loop.ts</code></td><td>专用分支，不经过 <code>runTool</code> / 审批</td></tr><tr><td><code>agent/worker.ts</code></td><td><code>op: ask_user_answer</code> / <code>ask_user_skip</code></td></tr><tr><td><code>src/spawn.ts</code></td><td><code>answerAskUser()</code> / <code>skipAskUser()</code></td></tr><tr><td><code>src/sidebar.ts</code></td><td><code>AskUserPending</code> 追问卡片</td></tr></tbody></table><hr><h2 id="_4-文件一览" tabindex="-1">4. 文件一览 <a class="header-anchor" href="#_4-文件一览" aria-label="Permalink to &quot;4. 文件一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>agent/tavily.ts</code></td><td>Tavily 搜索</td></tr><tr><td><code>agent/autoApprove.ts</code></td><td>只读自动放行</td></tr><tr><td><code>agent/askUser.ts</code></td><td>用户追问</td></tr><tr><td><code>agent/tools.ts</code></td><td><code>getToolDefinitions()</code></td></tr><tr><td><code>agent/system.ts</code></td><td><code>getPluginSystem()</code></td></tr><tr><td><code>src/extension.ts</code></td><td>Key 注入子进程</td></tr></tbody></table><hr><h2 id="_5-vs-code-动手" tabindex="-1">5. VS Code 动手 <a class="header-anchor" href="#_5-vs-code-动手" aria-label="Permalink to &quot;5. VS Code 动手&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ch45:compile</span></span></code></pre></div><ol><li>打开 <strong><code>lessons/45-web-search</code></strong> → <strong>F5</strong></li><li><code>bagent: 打开 Agent 面板（web_search）</code></li><li><code>/config</code> 看联网状态</li><li>试一句会触发澄清的问题，例如：「帮我在项目里加一个部署脚本」（观察是否 <code>ask_user_question</code>）</li><li>分别试 <strong>提交</strong> 与 <strong>跳过</strong></li></ol><hr><h2 id="_6-终端动手" tabindex="-1">6. 终端动手 <a class="header-anchor" href="#_6-终端动手" aria-label="Permalink to &quot;6. 终端动手&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-...</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TAVILY_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tvly-...   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 可选</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ch45</span></span></code></pre></div><p>追问时终端会打印 <code>[追问] …</code>，回车即跳过。</p><hr><h2 id="_7-与第-44-课关系" tabindex="-1">7. 与第 44 课关系 <a class="header-anchor" href="#_7-与第-44-课关系" aria-label="Permalink to &quot;7. 与第 44 课关系&quot;">​</a></h2><ul><li><strong>第 44 课</strong>：读文件分发</li><li><strong>第 45 课</strong>：fork 44 + 联网 + 自动放行 + 用户追问；<strong>不修改</strong> 40 / 44</li></ul><hr><h2 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h2><ul><li>[ ] 无 Tavily Key 时工具列表无 <code>web_search</code>？</li><li>[ ] <code>read_file</code> 读 cwd 下普通文件自动放行？</li><li>[ ] <code>ask_user_question</code> 出现追问 UI，跳过返回 hint？</li><li>[ ] 跳过后 Agent 是否继续任务、不死循环追问？</li></ul><hr><p><a href="/bagent/chapters/44-read-dispatch.html">← 第 44 课</a> · <a href="/bagent/chapters/09-tavily.html">第 9 课 · Tavily</a></p>`,49)])])}const g=t(o,[["render",d]]);export{k as __pageData,g as default};
